#include "legacy_irq_runtime.h"
#include <assert.h>
#include <stdio.h>
struct io{uint64_t ctl;unsigned writes,fail;};static bool rd(void*c,uint32_t f,uint64_t*v){struct io*i=c;assert(f==0x4002);*v=i->ctl;return true;}static bool wr(void*c,uint32_t f,uint64_t v){struct io*i=c;if(++i->writes==i->fail)return false;if(f==0x4002)i->ctl=v;return true;}
static void init(struct lir*s){assert(lir_init(s,1,UINT64_C(4)<<32));uint8_t v=0x11;assert(pic0_access(&s->timer.pic,0x20,true,&v));v=0x20;assert(pic0_access(&s->timer.pic,0x21,true,&v));v=4;assert(pic0_access(&s->timer.pic,0x21,true,&v));v=1;assert(pic0_access(&s->timer.pic,0x21,true,&v));v=0xfe;assert(pic0_access(&s->timer.pic,0x21,true,&v));assert(pic0_edges(&s->timer.pic,1,1));}
int main(void){struct lir s;struct io io={.ctl=0x80000000};struct lei_snapshot g={.rflags=2};init(&s);assert(lir_before(&s,&g,&io,rd,wr));assert(io.ctl&4);assert(!s.timer.pic.reserved);assert(lir_after(&s,PGG_EXIT,7,0,&io,wr));g.rflags=0x202;g.activity=1;assert(lir_before(&s,&g,&io,rd,wr));assert(!(io.ctl&4)&&s.timer.pic.reserved);assert(lir_after(&s,PGG_EXIT,30,0,&io,wr));assert(s.timer.pic.isr&&!s.timer.pic.irr);init(&s);io=(struct io){.ctl=0x80000000};assert(lir_before(&s,&g,&io,rd,wr));assert(lir_after(&s,PGG_NO_ENTRY,0,0,&io,wr));assert(!s.timer.pic.reserved&&s.timer.pic.irr);init(&s);assert(lir_before(&s,&g,&io,rd,wr));assert(!lir_after(&s,PGG_EXIT,52,0,&io,wr)&&s.failed&&s.timer.pic.reserved);for(unsigned f=1;f<=3;f++){init(&s);io=(struct io){.ctl=0x80000000,.fail=f};assert(!lir_before(&s,&g,&io,rd,wr)&&s.failed&&s.timer.pic.reserved);}puts("legacy IRQ/window/HLT gate composition host PASS; not dispatcher");}
